if (window.PRODUTOS && Array.isArray(window.PRODUTOS_EUROPA)) {
  window.PRODUTOS_EUROPA = PRODUTOS_EUROPA.filter(produto => !/key\s*chain|chaveiro/i.test(produto.nome));
  let proximoIdEuropa = Math.max(0, ...PRODUTOS.map(produto => produto.id)) + 1;
  PRODUTOS_EUROPA.forEach(produto => {
    produto.id = proximoIdEuropa++;
    produto.preco = 199;
    produto.caracteristicas = ['Galeria completa do produto', 'Curadoria GLT Imports', produto.liga];
  });
  PRODUTOS.push(...PRODUTOS_EUROPA);
}
